use std::env;
use std::fs;
use std::process;
use std::path::Path;

#[derive(Debug, Clone, PartialEq, Eq)]
enum TokenKind {
    Whitespace,
    Comment,
    KeywordLet,
    KeywordIn,
    KeywordIf,
    KeywordThen,
    KeywordElse,
    KeywordInherit,
    Identifier,
    String,
    Number,
    True,
    False,
    Null,
    Eq,
    Neq,
    Assign,
    Semi,
    Dot,
    LParen,
    RParen,
    LBrace,
    RBrace,
    LBracket,
    RBracket,
    Other,
    Eof,
}

#[derive(Debug, Clone)]
struct Token {
    kind: TokenKind,
    text: String,
    line: usize,
    col: usize,
}

struct Lexer<'a> {
    input: &'a str,
    pos: usize,
    line: usize,
    col: usize,
}

impl<'a> Lexer<'a> {
    fn new(input: &'a str) -> Self {
        Self { input, pos: 0, line: 1, col: 1 }
    }

    fn next_token(&mut self) -> Token {
        if self.pos >= self.input.len() {
            return Token { kind: TokenKind::Eof, text: "".to_string(), line: self.line, col: self.col };
        }

        let start_pos = self.pos;
        let start_line = self.line;
        let start_col = self.col;

        let c = self.input[self.pos..].chars().next().unwrap();

        if c.is_whitespace() {
            while self.pos < self.input.len() && self.input[self.pos..].chars().next().unwrap().is_whitespace() {
                self.advance();
            }
            return Token { kind: TokenKind::Whitespace, text: self.input[start_pos..self.pos].to_string(), line: start_line, col: start_col };
        }

        if c == '#' {
            while self.pos < self.input.len() && self.input[self.pos..].chars().next().unwrap() != '\n' {
                self.advance();
            }
            return Token { kind: TokenKind::Comment, text: self.input[start_pos..self.pos].to_string(), line: start_line, col: start_col };
        }

        if self.input[self.pos..].starts_with("==") {
            self.advance(); self.advance();
            return Token { kind: TokenKind::Eq, text: "==".to_string(), line: start_line, col: start_col };
        }

        if self.input[self.pos..].starts_with("!=") {
            self.advance(); self.advance();
            return Token { kind: TokenKind::Neq, text: "!=".to_string(), line: start_line, col: start_col };
        }

        match c {
            '=' => { self.advance(); Token { kind: TokenKind::Assign, text: "=".to_string(), line: start_line, col: start_col } }
            ';' => { self.advance(); Token { kind: TokenKind::Semi, text: ";".to_string(), line: start_line, col: start_col } }
            '.' => { self.advance(); Token { kind: TokenKind::Dot, text: ".".to_string(), line: start_line, col: start_col } }
            '(' => { self.advance(); Token { kind: TokenKind::LParen, text: "(".to_string(), line: start_line, col: start_col } }
            ')' => { self.advance(); Token { kind: TokenKind::RParen, text: ")".to_string(), line: start_line, col: start_col } }
            '{' => { self.advance(); Token { kind: TokenKind::LBrace, text: "{".to_string(), line: start_line, col: start_col } }
            '}' => { self.advance(); Token { kind: TokenKind::RBrace, text: "}".to_string(), line: start_line, col: start_col } }
            '[' => { self.advance(); Token { kind: TokenKind::LBracket, text: "[".to_string(), line: start_line, col: start_col } }
            ']' => { self.advance(); Token { kind: TokenKind::RBracket, text: "]".to_string(), line: start_line, col: start_col } }
            _ if c.is_alphabetic() || c == '_' => {
                while self.pos < self.input.len() {
                    let c = self.input[self.pos..].chars().next().unwrap();
                    if c.is_alphanumeric() || c == '_' || c == '-' {
                        self.advance();
                    } else {
                        break;
                    }
                }
                let text = &self.input[start_pos..self.pos];
                let kind = match text {
                    "let" => TokenKind::KeywordLet,
                    "in" => TokenKind::KeywordIn,
                    "if" => TokenKind::KeywordIf,
                    "then" => TokenKind::KeywordThen,
                    "else" => TokenKind::KeywordElse,
                    "inherit" => TokenKind::KeywordInherit,
                    "true" => TokenKind::True,
                    "false" => TokenKind::False,
                    "null" => TokenKind::Null,
                    _ => TokenKind::Identifier,
                };
                Token { kind, text: text.to_string(), line: start_line, col: start_col }
            }
            '"' => {
                self.advance();
                while self.pos < self.input.len() {
                    let c = self.input[self.pos..].chars().next().unwrap();
                    if c == '"' {
                        self.advance();
                        break;
                    } else if c == '\\' {
                        self.advance();
                        if self.pos < self.input.len() { self.advance(); }
                    } else {
                        self.advance();
                    }
                }
                Token { kind: TokenKind::String, text: self.input[start_pos..self.pos].to_string(), line: start_line, col: start_col }
            }
            _ => {
                self.advance();
                Token { kind: TokenKind::Other, text: self.input[start_pos..self.pos].to_string(), line: start_line, col: start_col }
            }
        }
    }

    fn advance(&mut self) {
        let c = self.input[self.pos..].chars().next().unwrap();
        self.pos += c.len_utf8();
        if c == '\n' {
            self.line += 1;
            self.col = 1;
        } else {
            self.col += 1;
        }
    }
}

