fn run_check(args: &[String]) {
    let mut target = ".";
    let mut format = "stderr";

    let mut i = 0;
    while i < args.len() {
        match args[i].as_str() {
            "-o" | "--format" => {
                if i + 1 < args.len() {
                    format = &args[i+1];
                    i += 2;
                } else {
                    eprintln!("error: --format requires an argument");
                    process::exit(1);
                }
            }
            arg if arg.starts_with("-") => {
                i += 1;
            }
            arg => {
                target = arg;
                i += 1;
            }
        }
