fn check_dir(dir: &str, format: &str) -> bool {
    let mut found = false;
    if let Ok(entries) = fs::read_dir(dir) {
        for entry in entries.flatten() {
            let path = entry.path();
            if path.is_dir() {
                if path.file_name().and_then(|s| s.to_str()) != Some(".git") {
                    found |= check_dir(path.to_str().unwrap(), format);
                }
            } else if path.extension().and_then(|s| s.to_str()) == Some("nix") {
                found |= check_file(path.to_str().unwrap(), format);
            }
        }
    }
    found
