           tokens[i+2].kind == TokenKind::Eq &&
           tokens[i+3].kind == TokenKind::Whitespace &&
           tokens[i+4].kind == TokenKind::True {
            return Some(format!("Comparing `{}` with boolean literal `true`", tokens[i].text));
