           tokens[i+2].kind == TokenKind::KeywordIn {
            return Some("This let-in block is empty".to_string());
        }
    }
    None
}

fn check_w23(tokens: &[Token], i: usize) -> Option<String> {
    if i + 4 < tokens.len() {
        if tokens[i].kind == TokenKind::LBracket &&
           tokens[i+1].kind == TokenKind::RBracket &&
           tokens[i+2].kind == TokenKind::Whitespace &&
           tokens[i+3].kind == TokenKind::PlusPlus &&
           tokens[i+4].kind == TokenKind::Whitespace {
            return Some("Concatenating with an empty list".to_string());
        }
    }
    None
}

