        if self.input[self.pos..].starts_with("==") { self.advance(); self.advance(); return Token { kind: TokenKind::Eq, text: "==".to_string(), line: start_line, col: start_col, start: start_pos }; }
        if self.input[self.pos..].starts_with("!=") { self.advance(); self.advance(); return Token { kind: TokenKind::Neq, text: "!=".to_string(), line: start_line, col: start_col, start: start_pos }; }
        if self.input[self.pos..].starts_with("++") { self.advance(); self.advance(); return Token { kind: TokenKind::PlusPlus, text: "++".to_string(), line: start_line, col: start_col, start: start_pos }; }
        match c {
            '=' => { self.advance(); Token { kind: TokenKind::Assign, text: "=".to_string(), line: start_line, col: start_col, start: start_pos } }
            ';' => { self.advance(); Token { kind: TokenKind::Semi, text: ";".to_string(), line: start_line, col: start_col, start: start_pos } }
            '.' => { self.advance(); Token { kind: TokenKind::Dot, text: ".".to_string(), line: start_line, col: start_col, start: start_pos } }
            '(' => { self.advance(); Token { kind: TokenKind::LParen, text: "(".to_string(), line: start_line, col: start_col, start: start_pos } }
            ')' => { self.advance(); Token { kind: TokenKind::RParen, text: ")".to_string(), line: start_line, col: start_col, start: start_pos } }
            '{' => { self.advance(); Token { kind: TokenKind::LBrace, text: "{".to_string(), line: start_line, col: start_col, start: start_pos } }
            '}' => { self.advance(); Token { kind: TokenKind::RBrace, text: "}".to_string(), line: start_line, col: start_col, start: start_pos } }
            '[' => { self.advance(); Token { kind: TokenKind::LBracket, text: "[".to_string(), line: start_line, col: start_col, start: start_pos } }
            ']' => { self.advance(); Token { kind: TokenKind::RBracket, text: "]".to_string(), line: start_line, col: start_col, start: start_pos } }
            '?' => { self.advance(); Token { kind: TokenKind::Question, text: "?".to_string(), line: start_line, col: start_col, start: start_pos } }
            ':' => { self.advance(); Token { kind: TokenKind::Colon, text: ":".to_string(), line: start_line, col: start_col, start: start_pos } }
            _ if c.is_alphabetic() || c == '_' => {
                while self.pos < self.input.len() {
                    let c = self.input[self.pos..].chars().next().unwrap();
                    if c.is_alphanumeric() || c == '_' || c == '-' { self.advance(); } else { break; }
                }
                let text = &self.input[start_pos..self.pos];
                let kind = match text {
                    "let" => TokenKind::KeywordLet, "in" => TokenKind::KeywordIn, "if" => TokenKind::KeywordIf,
                    "then" => TokenKind::KeywordThen, "else" => TokenKind::KeywordElse, "inherit" => TokenKind::KeywordInherit,
                    "rec" => TokenKind::KeywordRec, "with" => TokenKind::KeywordWith, "true" => TokenKind::True,
                    "false" => TokenKind::False, "null" => TokenKind::Null, _ => TokenKind::Identifier,
                };
                Token { kind, text: text.to_string(), line: start_line, col: start_col, start: start_pos }
            }
            '"' => {
                self.advance();
                while self.pos < self.input.len() {
                    let c = self.input[self.pos..].chars().next().unwrap();
                    if c == '"' { self.advance(); break; } else if c == '\\' { self.advance(); if self.pos < self.input.len() { self.advance(); } } else { self.advance(); }
                }
                Token { kind: TokenKind::String, text: self.input[start_pos..self.pos].to_string(), line: start_line, col: start_col, start: start_pos }
            }
            _ => { self.advance(); Token { kind: TokenKind::Other, text: self.input[start_pos..self.pos].to_string(), line: start_line, col: start_col, start: start_pos } }
        }
    }
    fn advance(&mut self) {
        let c = self.input[self.pos..].chars().next().unwrap();
        self.pos += c.len_utf8();
        if c == '\n' { self.line += 1; self.col = 1; } else { self.col += 1; }
    }
}

struct Warning {
    line: usize, col: usize, start: usize, end: usize, code: String, title: String, msg: String, fix: Option<String>,
}

fn run_check(args: &[String]) {
    let mut target = ".";
    let mut format = "stderr";
    let mut i = 0;
    while i < args.len() {
        match args[i].as_str() {
            "-o" | "--format" => { i += 2; format = &args[i-1]; }
            arg if arg.starts_with("-") => { i += 1; }
            arg => { target = arg; i += 1; }
        }
    }
    let found = if Path::new(target).is_dir() { check_dir(target, format) } else { check_file(target, format) };
    process::exit(if found { 1 } else { 0 });
}

fn check_dir(dir: &str, format: &str) -> bool {
    let mut found = false;
    if let Ok(entries) = fs::read_dir(dir) {
        for entry in entries.flatten() {
            let path = entry.path();
            if path.is_dir() { if path.file_name().and_then(|s| s.to_str()) != Some(".git") { found |= check_dir(path.to_str().unwrap(), format); } }
            else if path.extension().and_then(|s| s.to_str()) == Some("nix") { found |= check_file(path.to_str().unwrap(), format); }
        }
    }
    found
}

fn get_warnings(path: &str, content: &str) -> Vec<Warning> {
    let mut lexer = Lexer::new(content);
    let mut tokens = Vec::new();
    loop { let tok = lexer.next_token(); if tok.kind == TokenKind::Eof { break; } tokens.push(tok); }
    let mut warnings = Vec::new();
    for i in 0..tokens.len() {
        // W01: x == true
        if i + 4 < tokens.len() && tokens[i].kind == TokenKind::Identifier && tokens[i+1].kind == TokenKind::Whitespace &&
           tokens[i+2].kind == TokenKind::Eq && tokens[i+3].kind == TokenKind::Whitespace && tokens[i+4].kind == TokenKind::True {
            warnings.push(Warning { line: tokens[i].line, col: tokens[i].col, start: tokens[i].start, end: tokens[i+4].start + tokens[i+4].text.len(),
                code: "W01".to_string(), title: "Unnecessary comparison with boolean".to_string(),
                msg: format!("Comparing `{}` with boolean literal `true`", tokens[i].text), fix: Some(tokens[i].text.clone()) });
        }
        // W02: let in x
        if i + 2 < tokens.len() && tokens[i].kind == TokenKind::KeywordLet && tokens[i+1].kind == TokenKind::Whitespace && tokens[i+2].kind == TokenKind::KeywordIn {
            warnings.push(Warning { line: tokens[i].line, col: tokens[i].col, start: tokens[i].start, end: tokens[i+2].start + tokens[i+2].text.len(),
                code: "W02".to_string(), title: "Empty let in".to_string(), msg: "This let-in block is empty".to_string(), fix: Some("".to_string()) });
        }
        // W23: [] ++ x
        if i + 4 < tokens.len() && tokens[i].kind == TokenKind::LBracket && tokens[i+1].kind == TokenKind::RBracket &&
           tokens[i+2].kind == TokenKind::Whitespace && tokens[i+3].kind == TokenKind::PlusPlus && tokens[i+4].kind == TokenKind::Whitespace {
            warnings.push(Warning { line: tokens[i].line, col: tokens[i].col, start: tokens[i].start, end: tokens[i+4].start,
                code: "W23".to_string(), title: "Empty list concatenation".to_string(), msg: "Concatenating with an empty list".to_string(), fix: Some("".to_string()) });
        }
    }
    warnings
}

fn check_file(path: &str, format: &str) -> bool {
    let content = fs::read_to_string(path).unwrap_or_default();
    let warnings = get_warnings(path, &content);
    for w in &warnings {
        if format == "errfmt" { println!("{}>{}:{}:{}:1:{}", path, w.line, w.col, w.code, w.msg); }
        else {
            println!("\x1b[33m[{}] Warning:\x1b[0m {}", w.code, w.title);
            println!("   \x1b[38;5;246m╭─[\x1b[0m{}:{}:{}\x1b[38;5;246m]\x1b[0m", path, w.line, w.col);
            println!("   \x1b[38;5;246m│\x1b[0m");
            let lines: Vec<&str> = content.lines().collect();
            if w.line <= lines.len() { println!(" {:2} \x1b[38;5;246m│\x1b[0m {}", w.line, lines[w.line-1]); }
            println!("   \x1b[38;5;246m·\x1b[0m    \x1b[35m────┬────\x1b[0m  ");
            println!("   \x1b[38;5;246m·\x1b[0m        \x1b[35m╰──────\x1b[0m {}", w.msg);
            println!("\x1b[38;5;246m───╯\x1b[0m");
        }
    }
    !warnings.is_empty()
}

fn run_fix(args: &[String]) {
    let mut target = ".";
    let mut dry_run = false;
    for arg in args {
        if arg == "--dry-run" || arg == "-d" { dry_run = true; }
        else if !arg.starts_with("-") { target = arg; }
    }
    if Path::new(target).is_dir() { fix_dir(target, dry_run); } else { fix_file(target, dry_run); }
}

fn fix_dir(dir: &str, dry_run: bool) {
    if let Ok(entries) = fs::read_dir(dir) {
        for entry in entries.flatten() {
            let path = entry.path();
            if path.is_dir() { if path.file_name().and_then(|s| s.to_str()) != Some(".git") { fix_dir(path.to_str().unwrap(), dry_run); } }
            else if path.extension().and_then(|s| s.to_str()) == Some("nix") { fix_file(path.to_str().unwrap(), dry_run); }
        }
    }
}

fn fix_file(path: &str, dry_run: bool) {
    let content = fs::read_to_string(path).unwrap_or_default();
    let mut warnings = get_warnings(path, &content);
    if warnings.is_empty() { return; }
    warnings.sort_by_key(|w| w.start);
    let mut new_content = String::new();
    let mut last_end = 0;
    for w in warnings {
        if let Some(replacement) = w.fix {
            new_content.push_str(&content[last_end..w.start]);
            new_content.push_str(&replacement);
            last_end = w.end;
        }
    }
    new_content.push_str(&content[last_end..]);
    if dry_run {
        println!("--- {}\n+++ {} [fixed]\n@@ -1,{} +1,{} @@", path, path, content.lines().count(), new_content.lines().count());
        // Simple diff (could be better)
        for line in new_content.lines() { println!("+{}", line); }
    } else {
        fs::write(path, new_content).unwrap();
    }
}

