}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 { print_help(); return; }
    match args[1].as_str() {
        "check" => run_check(&args[2..]), "list" => run_list(), "explain" => run_explain(&args[2..]),
        "dump" => run_dump(), "fix" => run_fix(&args[2..]), "-V" | "--version" => println!("statix 0.5.8"),
        "help" | "--help" | "-h" => print_help(),
        _ => { eprintln!("error: unrecognized subcommand '{}'", args[1]); process::exit(1); }
