}

struct Warning { line: usize, col: usize, start: usize, end: usize, code: String, title: String, msg: String, fix: Option<String> }

fn get_warnings(content: &str) -> Vec<Warning> {
    let mut lexer = Lexer::new(content);
    let mut tokens = Vec::new();
    loop { let tok = lexer.next_token(); if tok.kind == TokenKind::Eof { break; } tokens.push(tok); }
    let mut warnings = Vec::new();
    for i in 0..tokens.len() {
        if i + 4 < tokens.len() && tokens[i].kind == TokenKind::Identifier && tokens[i+1].kind == TokenKind::Whitespace &&
           tokens[i+2].kind == TokenKind::Eq && tokens[i+3].kind == TokenKind::Whitespace && tokens[i+4].kind == TokenKind::True {
            warnings.push(Warning { line: tokens[i].line, col: tokens[i].col, start: tokens[i].start, end: tokens[i+4].start + tokens[i+4].text.len(),
                code: "W01".to_string(), title: "Unnecessary comparison with boolean".to_string(),
                msg: format!("Comparing `{}` with boolean literal `true`", tokens[i].text), fix: Some(tokens[i].text.clone()) });
        }
        if i + 2 < tokens.len() && tokens[i].kind == TokenKind::KeywordLet && tokens[i+1].kind == TokenKind::Whitespace && tokens[i+2].kind == TokenKind::KeywordIn {
            warnings.push(Warning { line: tokens[i].line, col: tokens[i].col, start: tokens[i].start, end: tokens[i+2].start + tokens[i+2].text.len(),
                code: "W02".to_string(), title: "Empty let in".to_string(), msg: "This let-in block is empty".to_string(), fix: Some("".to_string()) });
        }
        if i + 2 < tokens.len() && tokens[i].kind == TokenKind::KeywordIn && tokens[i+1].kind == TokenKind::Whitespace && tokens[i+2].kind == TokenKind::KeywordLet {
            warnings.push(Warning { line: tokens[i].line, col: tokens[i].col, start: tokens[i].start, end: tokens[i+2].start + tokens[i+2].text.len(),
                code: "W06".to_string(), title: "Collapsible let in".to_string(), msg: "This let-in block can be collapsed".to_string(), fix: Some("".to_string()) });
        }
    }
    warnings
}

fn run_check(args: &[String]) {
    let mut target = "."; let mut format = "stderr"; let mut i = 0;
    while i < args.len() { match args[i].as_str() { "-o" | "--format" => { i += 2; format = &args[i-1]; } _ => { if !args[i].starts_with("-") { target = &args[i]; } i += 1; } } }
    let found = if Path::new(target).is_dir() { check_dir(target, format) } else { check_file(target, format) };
    process::exit(if found { 1 } else { 0 });
}

fn check_dir(dir: &str, format: &str) -> bool {
    let mut found = false;
    if let Ok(entries) = fs::read_dir(dir) {
        for entry in entries.flatten() {
            let path = entry.path();
            if path.is_dir() { if path.file_name().and_then(|s| s.to_str()) != Some(".git") { found |= check_dir(path.to_str().unwrap(), format); } }
            else if path.extension().and_then(|s| s.to_str()) == Some("nix") { found |= check_file(path.to_str().unwrap(), format); }
        }
    }
    found
}

fn check_file(path: &str, format: &str) -> bool {
    let content = fs::read_to_string(path).unwrap_or_default();
    let warnings = get_warnings(&content);
    for w in &warnings {
        if format == "errfmt" { println!("{}>{}:{}:{}:1:{}", path, w.line, w.col, w.code, w.msg); }
        else {
            println!("\x1b[33m[{}] Warning:\x1b[0m {}", w.code, w.title);
            println!("   \x1b[38;5;246m╭─[\x1b[0m{}:{}:{}\x1b[38;5;246m]\x1b[0m", path, w.line, w.col);
            println!("   \x1b[38;5;246m│\x1b[0m");
            let lines: Vec<&str> = content.lines().collect();
            if w.line <= lines.len() { println!(" {:2} \x1b[38;5;246m│\x1b[0m {}", w.line, lines[w.line-1]); }
            println!("   \x1b[38;5;246m·\x1b[0m    \x1b[35m────┬────\x1b[0m  ");
            println!("   \x1b[38;5;246m·\x1b[0m        \x1b[35m╰──────\x1b[0m {}", w.msg);
            println!("\x1b[38;5;246m───╯\x1b[0m");
        }
    }
    !warnings.is_empty()
}

fn run_fix(args: &[String]) {
    let mut target = "."; let mut dry_run = false;
    for arg in args { if arg == "--dry-run" || arg == "-d" { dry_run = true; } else if !arg.starts_with("-") { target = arg; } }
    if Path::new(target).is_dir() { fix_dir(target, dry_run); } else { fix_file(target, dry_run); }
}

fn fix_dir(dir: &str, dry_run: bool) {
    if let Ok(entries) = fs::read_dir(dir) {
        for entry in entries.flatten() {
            let path = entry.path();
            if path.is_dir() { if path.file_name().and_then(|s| s.to_str()) != Some(".git") { fix_dir(path.to_str().unwrap(), dry_run); } }
            else if path.extension().and_then(|s| s.to_str()) == Some("nix") { fix_file(path.to_str().unwrap(), dry_run); }
        }
    }
}

fn fix_file(path: &str, dry_run: bool) {
    let content = fs::read_to_string(path).unwrap_or_default();
    let mut warnings = get_warnings(&content);
    if warnings.is_empty() { return; }
    warnings.sort_by_key(|w| w.start);
    let mut new_content = String::new();
    let mut last_end = 0;
    for w in warnings {
        if let Some(replacement) = w.fix {
            new_content.push_str(&content[last_end..w.start]);
            new_content.push_str(&replacement);
            last_end = w.end;
        }
    }
    new_content.push_str(&content[last_end..]);
    if dry_run {
        let temp_fixed = format!("{}.fixed", path);
        fs::write(&temp_fixed, &new_content).unwrap();
        let output = process::Command::new("diff").arg("-u").arg(path).arg(&temp_fixed).output().unwrap();
        let diff_str = String::from_utf8_lossy(&output.stdout);
        let lines: Vec<&str> = diff_str.lines().collect();
        if lines.len() >= 2 {
            println!("--- {}", path);
            println!("+++ {} [fixed]", path);
            for line in &lines[2..] { println!("{}", line); }
        }
        fs::remove_file(temp_fixed).unwrap();
    } else { fs::write(path, new_content).unwrap(); }
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 { print_help(); return; }
    match args[1].as_str() {
        "check" => run_check(&args[2..]), "list" => run_list(), "explain" => run_explain(&args[2..]),
