#[derive(Debug, Clone, PartialEq, Eq)]
enum TokenKind {
    Whitespace, Comment, KeywordLet, KeywordIn, KeywordIf, KeywordThen, KeywordElse,
    KeywordInherit, KeywordRec, KeywordWith, Identifier, String, Number, True, False, Null,
