impl<'a> Lexer<'a> {
    fn new(input: &'a str) -> Self { Self { input, pos: 0, line: 1, col: 1 } }
    fn next_token(&mut self) -> Token {
        if self.pos >= self.input.len() {
            return Token { kind: TokenKind::Eof, text: "".to_string(), line: self.line, col: self.col, start: self.pos };
