            ';' => { self.advance(); Token { kind: TokenKind::Semi, text: ";".to_string(), line: start_line, col: start_col, start: start_pos } }
            '.' => { self.advance(); Token { kind: TokenKind::Dot, text: ".".to_string(), line: start_line, col: start_col, start: start_pos } }
            '(' => { self.advance(); Token { kind: TokenKind::LParen, text: "(".to_string(), line: start_line, col: start_col, start: start_pos } }
            ')' => { self.advance(); Token { kind: TokenKind::RParen, text: ")".to_string(), line: start_line, col: start_col, start: start_pos } }
